/// @custom
void SplitColour(float4 V, out float3 Head, out float Tail)
{
    Head = V.rgb;
    Tail = V.a;
}

export void M_DCustomOutParams(inout material m)
{
    float3 Head;
    float Tail;
    SplitColour(float4(1.0, 0.5, 0.25, 0.75), Head, Tail);

    m.EmissiveColor = Head;
    m.Opacity = Tail;
}
